Section BitStreamFast.
  Variable src : list Z.

  (* [comment removed for export] *)
  Definition reload_internal (d : bitD) : res (dstatus * bitD) :=
    let p := bd_ptr d - Z.shiftr (bd_bits d) 3 in
    let! c := readLE64 src p in
    Ok (Unfinished, mkBD c (Z.land (bd_bits d) 7) p false).

  (* [comment removed for export] *)
  Definition reload_dstream_fast (d : bitD) : res (dstatus * bitD) :=
    if bd_zero d then Ok (Overflow, d)            (* [comment removed for export] *)
    else if bd_ptr d <? 8 then Ok (Overflow, d)
    else reload_internal d.
End BitStreamFast.

(* [comment removed for export] *)
Definition end_of_dstream (d : bitD) : bool :=
  negb (bd_zero d) && (bd_ptr d =? 0) && (bd_bits d =? 64).

