(* [comment removed for export] *)
Definition bitD_ok (len : Z) (d : bitD) : Prop :=
  0 <= bd_cont d < 2^64 /\ 0 <= bd_bits d < 2^32 /\ 0 <= bd_ptr d /\
  (bd_ptr d = 0 \/ bd_ptr d + 8 <= len).

