  (* [comment removed for export] *)
  Lemma reload_dstream_ok d : bitD_ok len d -> bd_zero d = false ->
    exists st d', reload_dstream src d = Ok (st, d') /\ bitD_ok len d' /\
      (st = Unfinished -> 0 <= bd_bits d' <= 7 /\ bd_zero d' = false) /\
      (bd_zero d' = true -> st = Overflow) /\
